{"type":"item.started","item":{"id":"item_95","type":"command_execution","command":"/bin/zsh -lc "sed -n '1051,1580p' packages/main/src/core/managed-host-run.ts"","aggregated_output":"","exit_code":null,"status":"in_progress"}}
{"type":"item.completed","item":{"id":"item_95","type":"command_execution","command":"/bin/zsh -lc "sed -n '1051,1580p' packages/main/src/core/managed-host-run.ts"","aggregated_output":"interface ManagedHostRunOutputJournalRead {
  frames: ManagedHostRunOutputFrame[];
