{"type":"item.completed","item":{"id":"item_99","type":"command_execution","command":"/bin/zsh -lc "sed -n '2111,2640p' packages/main/src/core/managed-host-run.ts"","aggregated_output":"    generation: current.generation + 1,
    workerPid: process.pid,
