        return cancel?.reason ?? (deadlineExceeded ? 'absolute_deadline_exceeded' : 'provider_launch_authority_revoked');
      }
      updateSnapshotUnlocked(paths, snapshot => ({ ...snapshot, providerLaunchState: 'granted' }));
